35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Digits(fraction = 0, integer = 10)
49	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date", columnDefinition = "DATE")
56	    private java.time.LocalDate registrationDate;
57	
58	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
59	    private Set<Pet> pets;
60	
61	    public java.time.LocalDate getRegistrationDate() {
62	        return this.registrationDate;
63	    }
64	
65	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
66	        this.registrationDate = registrationDate;
67	    }
68	
69	    public String getAddress() {
70	        return this.address;
71	    }
72	
73	    public void setAddress(String address) {
74	        this.address = address;
75	    }
76	
77	    public String getCity() {
78	        return this.city;
79	    }
80	
81	    public void setCity(String city) {
82	        this.city = city;
83	    }
84	
85	    public String getTelephone() {
86	        return this.telephone;
87	    }
88	
89	    public void setTelephone(String telephone) {
90	        this.telephone = telephone;
91	    }
92	
93	    public String getEmail() {
94	        return this.email;
95	    }
96	
97	    /** Store the address lower-cased so it is persisted and returned normalized. */
98	    public void setEmail(String email) {
99	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
100	    }
101	
102	    protected Set<Pet> getPetsInternal() {
103	        if (this.pets == null) {
104	            this.pets = new HashSet<>();
105	        }
106	        return this.pets;
107	    }
108	
109	    protected void setPetsInternal(Set<Pet> pets) {
110	        this.pets = pets;
111	    }
112	
113	    public List<Pet> getPets() {
114	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
115	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
116	        return Collections.unmodifiableList(sortedPets);
117	    }
118	
119	    public void setPets(List<Pet> pets) {
120	        this.pets = new HashSet<>(pets);
121	    }
122	
123	    public void addPet(Pet pet) {
124	        getPetsInternal().add(pet);
125	        pet.setOwner(this);
126	    }
127	
128	    /**
129	     * Return the Pet with the given name, or null if none found for this Owner.
130	     *
131	     * @param name to test
132	     * @return true if pet name is already in use
133	     */
134	    public Pet getPet(String name) {
135	        return getPet(name, false);
136	    }
137	
138	    /**
139	     * Return the Pet with the given name, or null if none found for this Owner.
140	     *
141	     * @param name to test
142	     * @return true if pet name is already in use
143	     */
144	    public Pet getPet(String name, boolean ignoreNew) {
145	        name = name.toLowerCase();
146	        for (Pet pet : getPetsInternal()) {
147	            if (!ignoreNew || !pet.isNew()) {
148	                String compName = pet.getName();
149	                compName = compName.toLowerCase();
150	                if (compName.equals(name)) {
151	                    return pet;
152	                }
153	            }
154	        }
155	        return null;
156	    }
157	
158	    public Pet getPet(Integer petId) {
159	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
160	    }
161	
162	    @Override
163	    public String toString() {
164	        return new ToStringCreator(this)
165	
166	            .append("id", this.getId())
167	            .append("new", this.isNew())
168	            .append("lastName", this.getLastName())
169	            .append("firstName", this.getFirstName())
170	            .append("address", this.address)
171	            .append("city", this.city)
172	            .append("telephone", this.telephone)
173	            .toString();
174	    }
175	}
