37	/**
38	 * Rejects a create/update owner request whose required text fields (firstName, lastName,
39	 * address, city, telephone) are missing or blank, responding 400 with a JSON body whose
40	 * {@code errors} array names each offending field. The check runs before Bean Validation
41	 * so blank (whitespace-only) values are caught in addition to absent ones.
42	 */
43	@ControllerAdvice
44	@Order(Ordered.HIGHEST_PRECEDENCE)
45	public class OwnerRequiredFieldsAdvice implements RequestBodyAdvice {
46	
47	    @Override
48	    public boolean supports(MethodParameter methodParameter, Type targetType,
49	                            Class<? extends HttpMessageConverter<?>> converterType) {
50	        return OwnerFieldsDto.class.equals(targetType);
51	    }
52	
53	    @Override
54	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
55	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
56	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
57	        List<String> missing = new ArrayList<>();
58	        addIfBlank(missing, "firstName", owner.getFirstName());
59	        addIfBlank(missing, "lastName", owner.getLastName());
60	        addIfBlank(missing, "address", owner.getAddress());
61	        addIfBlank(missing, "city", owner.getCity());
62	        addIfBlank(missing, "telephone", owner.getTelephone());
63	        if (!missing.isEmpty()) {
64	            throw new MissingOwnerFieldsException(missing);
65	        }
66	        return body;
67	    }
68	
69	    private void addIfBlank(List<String> missing, String field, String value) {
70	        if (value == null || value.isBlank()) {
71	            missing.add(field);
72	        }
73	    }
74	
75	    @Override
76	    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
77	                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
78	        return body;
79	    }
80	
81	    @Override
82	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
83	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
84	        return inputMessage;
85	    }
86	
87	    @ExceptionHandler(MissingOwnerFieldsException.class)
88	    @ResponseBody
89	    public ResponseEntity<Map<String, Object>> handleMissingOwnerFields(MissingOwnerFieldsException e) {
90	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", e.getFields()));
91	    }
92	
93	    /** Signals that one or more required owner fields were missing or blank. */
94	    static class MissingOwnerFieldsException extends RuntimeException {
95	
96	        private final List<String> fields;
97	
98	        MissingOwnerFieldsException(List<String> fields) {
99	            this.fields = fields;
100	        }
101	
102	        List<String> getFields() {
103	            return this.fields;
104	        }
105	    }
106	}
